> One way to achieve this is by using a state management library like React's Context or Redux to store the state of the form fields that need to be checked for changes.
> 
> Here is a general outline of the steps you could follow:
> 
> 1. Create a new context or Redux store to hold the form state.
> 1. In each component that has a form with changes that need to be checked, update the state when the form values change.
> 1. Add a useEffect hook to each of these components that listens for changes to the form state, and sets a flag to indicate that the form has unsaved changes.
> 1. Modify your SubmitButton component to check this flag before allowing the user to cancel. If the flag is set, display a confirmation dialog.
> 1. Add a function to reset the form state when the user submits the form or cancels with confirmation.
> 
> Here's some sample code to illustrate the steps:
> 
> ```tsx
> // Define a new context or Redux store to hold the form state
> import { createContext, useContext } from 'react';
> 
> interface FormState {
>   // Add properties for each form field that needs to be tracked
>   name: string;
>   email: string;
>   // ...
> }
> 
> interface FormContextType {
>   formState: FormState;
>   setFormState: (state: FormState) => void;
> }
> 
> const FormContext = createContext<FormContextType>({
>   formState: {},
>   setFormState: () => {},
> });
> 
> export function useFormContext() {
>   return useContext(FormContext);
> }
> 
> // In each component with a form, update the state when the form values change
> import { useFormContext } from './form-context';
> 
> export function MyForm() {
>   const { formState, setFormState } = useFormContext();
> 
>   function handleInputChange(event: React.ChangeEvent<HTMLInputElement>) {
>     const { name, value } = event.target;
>     setFormState((prevState) => ({ ...prevState, [name]: value }));
>   }
> 
>   // Add a useEffect hook to set a flag when the form state changes
>   const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
>   useEffect(() => {
>     setHasUnsavedChanges(true);
>   }, [formState]);
> 
>   // Add a function to reset the form state
>   function handleFormSubmit() {
>     setFormState({});
>     setHasUnsavedChanges(false);
>   }
> 
>   function handleCancel() {
>     if (hasUnsavedChanges) {
>       const confirmCancel = window.confirm('Are you sure you want to cancel? Any unsaved changes will be lost.');
>       if (confirmCancel) {
>         setFormState({});
>         setHasUnsavedChanges(false);
>       }
>     } else {
>       // If there are no unsaved changes, cancel immediately
>       // ...
>     }
>   }
> 
>   return (
>     <form>
>       <label>
>         Name:
>         <input type="text" name="name" value={formState.name} onChange={handleInputChange} />
>       </label>
>       <label>
>         Email:
>         <input type="email" name="email" value={formState.email} onChange={handleInputChange} />
>       </label>
>       {/* Add SubmitButton component with onClick handlers for submit and cancel */}
>       <SubmitButton onSubmit={handleFormSubmit} onCancel={handleCancel} />
>     </form>
>   );
> }
> 
> // Modify the SubmitButton component to check for unsaved changes
> interface SubmitButtonProps {
>   onSubmit: () => void;
>   onCancel: () => void;
> }
> 
> export function SubmitButton({ onSubmit, onCancel }: SubmitButtonProps) {
>   const { formState } = useFormContext();
> 
>   // Add a flag to check for unsaved changes
>   const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
> 
>   // Set the flag to true when the form state changes
>   useEffect(() => {
>     setHasUnsavedChanges(true);
>   }, [formState]);
> 
>   function handleSubmitClick() {
>     // Call onSubmit function to submit the form
>     onSubmit();
>   }
> 
>   function handleCancelClick() {
>     // If there are unsaved changes, display a confirmation dialog
>     if (hasUnsavedChanges) {
>       const confirmCancel = window.confirm('Are you sure you want to cancel? Any unsaved changes will be lost.');
>       if (confirmCancel) {
>         // Call onCancel function to cancel the form and reset the form state
>         onCancel();
>       }
>     } else {
>     // If there are no unsaved changes, cancel immediately
>     onCancel();
>     }
>   }
> 
>   return (
>     <div>
>       <button type="button" onClick={handleSubmitClick}>Submit</button>
>       <button type="button" onClick={handleCancelClick}>Cancel</button>
>     </div>
>   );
> }
> ```
> 
> Note that this is just one way to implement this functionality using a state management library like React's Context or Redux. There are other approaches you could take depending on your specific use case and preferences.
